create table RB_LIMIT_CTRL_CONF (DEAL_FLOW VARCHAR(1) null  ,LIMIT_CTRL_END_DATE TIMESTAMP(3) null  ,LIMIT_CTRL_END_TIME TIMESTAMP(3) null  ,TEMP_LIMIT_FLAG VARCHAR(1) null  ,CTRL_ITEM_TYPE VARCHAR(1) null  ,LIMIT_CTRL_NUM INT null  ,LIMIT_CTRL_BGN_DATE TIMESTAMP(3) null  ,PERIOD_TYPE VARCHAR(1) null  ,PERIOD_VALUE VARCHAR(5) null  ,LIMIT_BRANCH_ID VARCHAR(30) not null  ,LIMIT_CTRL_BGN_TIME TIMESTAMP(3) null  ,SUM_TYPE VARCHAR(1) null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,LIMIT_SCENE_NO VARCHAR(50) not null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,ALLOW_CUSTOM_FLAG VARCHAR(1) not null  ,ONLY_CUSTOM VARCHAR(1) null  ,LIMIT_BRANCH_RANGE VARCHAR(1) not null  ,VALID_FLAG VARCHAR(20) null  ,ALLOW_EXCEED_FLAG VARCHAR(1) null  ,LIMIT_CTRL_AMT DECIMAL(38,2) null  ,TEMP_LIMIT_VALID_TERM VARCHAR(5) null  , primary key(LIMIT_BRANCH_ID,LIMIT_SCENE_NO));